-- Director world v3: people, mandates, information quality and an immutable transfer market.
ALTER TABLE "DirectorCoach" ADD COLUMN "personality" TEXT NOT NULL DEFAULT 'PRAGMATIC', ADD COLUMN "reputation" DOUBLE PRECISION NOT NULL DEFAULT 50, ADD COLUMN "ambition" DOUBLE PRECISION NOT NULL DEFAULT 60, ADD COLUMN "interferenceTolerance" DOUBLE PRECISION NOT NULL DEFAULT 50, ADD COLUMN "preferredRoles" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "mandate" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "status" TEXT NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE "DirectorPlayer" ADD COLUMN "agentId" TEXT, ADD COLUMN "transferStatus" TEXT NOT NULL DEFAULT 'AVAILABLE';
ALTER TABLE "DirectorMatch" ADD COLUMN "seasonId" TEXT;
DROP INDEX IF EXISTS "DirectorMatch_careerId_round_homeClubId_awayClubId_key";
CREATE UNIQUE INDEX "DirectorMatch_careerId_seasonId_round_homeClubId_awayClubId_key" ON "DirectorMatch"("careerId", "seasonId", "round", "homeClubId", "awayClubId");

CREATE TABLE "DirectorAgent" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "name" TEXT NOT NULL, "personality" TEXT NOT NULL, "ambition" DOUBLE PRECISION NOT NULL, "negotiation" DOUBLE PRECISION NOT NULL, "loyalty" DOUBLE PRECISION NOT NULL, "priorities" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorAgent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorPlayerExpectation" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "expectedRole" TEXT NOT NULL, "targetMinuteShare" DOUBLE PRECISION NOT NULL, "actualMinuteShare" DOUBLE PRECISION NOT NULL DEFAULT 0, "wageSatisfaction" DOUBLE PRECISION NOT NULL DEFAULT 60, "ambition" DOUBLE PRECISION NOT NULL DEFAULT 55, "willingness" DOUBLE PRECISION NOT NULL DEFAULT 70, "escalationStage" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'SETTLED', "reasons" JSONB NOT NULL DEFAULT '[]', "lastEvaluatedDay" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorPlayerExpectation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorSquadGroup" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "clubId" TEXT NOT NULL, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "memberIds" JSONB NOT NULL DEFAULT '[]', "influence" DOUBLE PRECISION NOT NULL DEFAULT 50, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorSquadGroup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorStaff" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "clubId" TEXT, "role" TEXT NOT NULL, "name" TEXT NOT NULL, "ability" DOUBLE PRECISION NOT NULL, "personality" TEXT NOT NULL, "weeklyWage" INTEGER NOT NULL, "workload" DOUBLE PRECISION NOT NULL DEFAULT 35, "relationship" DOUBLE PRECISION NOT NULL DEFAULT 60, "contractUntil" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorStaff_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorTransferCase" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "sellingClubId" TEXT NOT NULL, "buyingClubId" TEXT NOT NULL, "kind" TEXT NOT NULL DEFAULT 'PERMANENT', "status" TEXT NOT NULL DEFAULT 'OPEN', "initiatedBy" TEXT NOT NULL, "playerAgreement" TEXT NOT NULL DEFAULT 'PENDING', "agreedDay" INTEGER, "registrationDay" INTEGER, "version" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorTransferCase_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorTransferOffer" ("id" TEXT NOT NULL, "caseId" TEXT NOT NULL, "round" INTEGER NOT NULL, "submittedByClubId" TEXT NOT NULL, "upfront" INTEGER NOT NULL DEFAULT 0, "installments" INTEGER NOT NULL DEFAULT 0, "bonuses" INTEGER NOT NULL DEFAULT 0, "sellOn" DOUBLE PRECISION NOT NULL DEFAULT 0, "loanFee" INTEGER NOT NULL DEFAULT 0, "optionFee" INTEGER, "swapPlayerId" TEXT, "weeklyWage" INTEGER NOT NULL, "years" INTEGER NOT NULL, "promisedRole" TEXT NOT NULL, "sellerUtility" DOUBLE PRECISION NOT NULL, "playerUtility" DOUBLE PRECISION NOT NULL, "response" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DirectorTransferOffer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorRegistration" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "caseId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "fromClubId" TEXT NOT NULL, "toClubId" TEXT NOT NULL, "effectiveDay" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "registeredAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DirectorRegistration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorCoachCandidate" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "name" TEXT NOT NULL, "personality" TEXT NOT NULL, "reputation" DOUBLE PRECISION NOT NULL, "ambition" DOUBLE PRECISION NOT NULL, "philosophy" TEXT NOT NULL, "formation" TEXT NOT NULL, "youthDevelopment" DOUBLE PRECISION NOT NULL, "manManagement" DOUBLE PRECISION NOT NULL, "matchManagement" DOUBLE PRECISION NOT NULL, "wageDemand" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'AVAILABLE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DirectorCoachCandidate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorCoachNegotiation" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "clubId" TEXT NOT NULL, "candidateId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "round" INTEGER NOT NULL DEFAULT 0, "patience" INTEGER NOT NULL DEFAULT 3, "proposedTerms" JSONB NOT NULL DEFAULT '{}', "history" JSONB NOT NULL DEFAULT '[]', "response" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorCoachNegotiation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorSeasonObjective" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "seasonId" TEXT NOT NULL, "clubId" TEXT NOT NULL, "kind" TEXT NOT NULL, "target" DOUBLE PRECISION NOT NULL, "weight" DOUBLE PRECISION NOT NULL, "progress" DOUBLE PRECISION, "status" TEXT NOT NULL DEFAULT 'TRACKING', "explanation" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorSeasonObjective_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorBoardReview" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "seasonId" TEXT NOT NULL, "clubId" TEXT NOT NULL, "kind" TEXT NOT NULL, "dayIndex" INTEGER NOT NULL, "sporting" DOUBLE PRECISION NOT NULL, "finance" DOUBLE PRECISION NOT NULL, "academy" DOUBLE PRECISION NOT NULL, "infrastructure" DOUBLE PRECISION NOT NULL, "overall" DOUBLE PRECISION NOT NULL, "outcome" TEXT NOT NULL, "explanation" JSONB NOT NULL DEFAULT '[]', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DirectorBoardReview_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DirectorJobOffer" ("id" TEXT NOT NULL, "careerId" TEXT NOT NULL, "clubId" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'DIRECTOR', "status" TEXT NOT NULL DEFAULT 'OPEN', "expiresDay" INTEGER NOT NULL, "terms" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DirectorJobOffer_pkey" PRIMARY KEY ("id"));

